<?php declare(strict_types=1); namespace App\Repositories; use PDO; final class LiquidityRoundRepository{private $pdo; public function __construct(?PDO $pdo=null){$this->pdo=$pdo??\App\Core\Database::connection();} public function createRound($sid,$r){$this->pdo->prepare('INSERT INTO liquidity_rounds (session_id,round_number) VALUES (?,?)')->execute([$sid,$r]);} public function getCurrentRound($sid,$r){$s=$this->pdo->prepare('SELECT * FROM liquidity_rounds WHERE session_id=? AND round_number=?');$s->execute([$sid,$r]);return $s->fetch()?:null;} public function closeRound($sid,$r){$this->pdo->prepare("UPDATE liquidity_rounds SET status='closed', ended_at=NOW() WHERE session_id=? AND round_number=? AND status='open'")->execute([$sid,$r]);} public function hasOpenRound($sid,$r){$s=$this->pdo->prepare("SELECT COUNT(*) FROM liquidity_rounds WHERE session_id=? AND round_number=? AND status='open'");$s->execute([$sid,$r]);return (int)$s->fetchColumn()>0;}}
